head.script:

scwin.onpageload = function() {

};

scwin.onpageunload = function() {

};

var i = 0;
scwin.fn_addTab = function(){
	var tabOpt = { 
			label : "임시화면" + i, 
			closable : false // true 시 닫기 버튼 생성
	}; 

	var contOpt = { 
		frameMode : "wframe" ,
		src : "tc_alwaysShowCloseBtn_closable_WESD-1776_(WSQ-5922)_sub.xml"
	};

	tabControl1.addTab('tab0' + i, tabOpt, contOpt);
	var idx = tabControl1.getTabCount();
	tabControl1.setSelectedTabIndex(idx-1);
	i++;
}

// 버튼 클릭 시 tab 추가
scwin.trigger2_onclick = function(e) {
	scwin.fn_addTab(); // 탭 생성
};

scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('tabControl1_tab_tabs1_close').style.display == 'block';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
